# walls from E6 (border + interior)
walls = set()
for r in range(10):
    for c in range(10):
        if r == 0 or r == 9 or c == 0 or c == 9:
            walls.add((r, c))
walls.update([(2,2),(2,3),(2,6),(2,7),(3,2),(3,7),(4,4),(4,5),
              (5,4),(5,5),(6,2),(6,7),(7,2),(7,3),(7,6),(7,7)])

agent = (4, 2)

def make_obs(agent, obj=None, reward=None, prev=None):
    x = np.zeros(500, dtype=float)
    for r, c in walls:
        x[(r*10+c)*5 + 3] = 1.0
    x[(agent[0]*10 + agent[1])*5 + 0] = 1.0
    if obj is not None:
        x[(obj[0]*10 + obj[1])*5 + 1] = 1.0
    if reward is not None:
        x[(reward[0]*10 + reward[1])*5 + 2] = 1.0
    if prev is not None:
        for r, c in prev:
            x[(r*10+c)*5 + 4] = 1.0
    return x

cells = [(r, c) for r in range(1, 9) for c in range(1, 9)]
prev_modes = [None, [agent]]
X = []
meta = []
for prev in prev_modes:
    for ch in [1, 2]:
        for cell in cells:
            valid = (cell not in walls and cell != agent)
            obj = cell if (ch == 1 and valid) else None
            rew = cell if (ch == 2 and valid) else None
            X.append(make_obs(agent, obj=obj, reward=rew, prev=prev))
            meta.append((prev is not None, ch, cell))

X = np.array(X)
logits = forward(X)
acts = np.argmax(logits, axis=1)
sym = ['0', '^', 'v', '<', '>']

def get_grid(prev_agent, ch):
    grid = {}
    for (pa, c, cell), a in zip(meta, acts):
        if pa == prev_agent and c == ch:
            grid[cell] = a
    return grid

def print_grid(grid, title):
    print(title)
    for r in range(1, 9):
        row = []
        for c in range(1, 9):
            if (r, c) in walls:
                row.append('#')
            elif (r, c) == agent:
                row.append('A')
            else:
                row.append(sym[grid[(r, c)]])
        print(' '.join(row))

print("Agent at", agent, "prev=agent (rows 1-8, cols 1-8)")
print_grid(get_grid(True, 1), "ch1 object -> action")
print_grid(get_grid(True, 2), "ch2 reward -> action")

# baseline from a wall-cell row (no object/reward)
for i, (pa, ch, cell) in enumerate(meta):
    if pa and ch == 1 and cell in walls:
        print("baseline action:", sym[acts[i]], "logits:", np.round(logits[i], 2))
        break

def counts(ch, mode):
    total = 0
    good = 0
    grid = get_grid(True, ch)
    for r in range(1, 9):
        for c in range(1, 9):
            if (r, c) in walls or (r, c) == agent:
                continue
            a = grid[(r, c)]
            dr = r - agent[0]
            dc = c - agent[1]
            if abs(dr) >= abs(dc):
                if mode == 'away':
                    target = 2 if dr < 0 else 1
                else:
                    target = 1 if dr < 0 else 2
            else:
                if mode == 'away':
                    target = 4 if dc < 0 else 3
                else:
                    target = 3 if dc < 0 else 4
            total += 1
            if a == target:
                good += 1
    return good, total

print("ch1 away-match:", counts(1, 'away'))
print("ch2 toward-match:", counts(2, 'toward'))

def diff_count(ch):
    cnt = 0
    g1 = get_grid(True, ch)
    g0 = get_grid(False, ch)
    for cell in cells:
        if g1[cell] != g0[cell]:
            cnt += 1
    return cnt

print("prev=agent vs prev=0 differ: ch1", diff_count(1), "ch2", diff_count(2))
